using Fm27Editor.Core.Players;

namespace Fm27Editor.Core.Tests;

public class FutureTransferRecordTemplateTests
{
    [Fact]
    public void RecordsMatchCapturedFmrteTransfer()
    {
        var offer = FutureTransferRecordTemplate.Offer(0x7FFAF19C4098, 0x17444B91CF8, 0x17424F53A08,
            0x17424F793A0, 12345678, 8335, 9639, 0x17428312930, new(2026, 9, 30), new(2027, 1, 1));
        Assert.Equal(Convert.FromHexString(""), offer);
        Assert.Equal(Convert.FromHexString("01000000000000000000000000000000502B312874010000000000000000000000000000000000008F200000816967FF000000000000000001006C07000002010100000000000000"), FutureTransferRecordTemplate.ContractLink(0x17428312B50, 8335));
        Assert.Equal(Convert.FromHexString("F81CB944740100000100EB078F20000000000000000000000000000000000000"), FutureTransferRecordTemplate.TransferDate(0x17444B91CF8, new(2027, 1, 1), 8335));
    }
}
